defmodule Mix.Tasks.Compile.Spex do
  # sexy_spex 0.1.0 does not ship a compile.spex compiler task, but the
  # CodeMySpec compiler chain expects one in the :test compilers list.
  # Spex specs run via `mix spex`; compilation itself needs no extra step.
  @moduledoc false

  use Mix.Task.Compiler

  @impl true
  def run(_args), do: {:ok, []}
end

